<script>
 import {onMount} from 'svelte';
 import {Sparkles,Film,Download,RefreshCw,X,ShieldCheck,ArrowRight} from 'lucide-svelte';
 import {apiRequest,syncLocalAsset} from '../generation-client.js';
 let {storyId,scene=null,kind='scene',prompt='',assets=[],entityId=null,title='',onassetschange=()=>{},notify=()=>{}}=$props();
 let session=$state(null),wallet=$state(null),jobs=$state([]),modelId=$state(''),aspectRatio=$state('16:9'),resolution=$state('Preview'),duration=$state(5),editablePrompt=$state(''),busy=$state(false),error=$state(''),intent=$state(null),loaded=$state(false),sourceAssetId=$state('');
 let available=$derived(session?.models.filter(m=>m.capabilities.includes(kind))||[]),model=$derived(available.find(m=>m.id===modelId)||available[0]);
 let estimate=$derived(session?.costs?.[kind]||0);
 let sceneJobs=$derived(jobs.filter(j=>j.storyId===storyId&&(scene?String(j.sceneId)===String(scene.id):true)));
 $effect(()=>{if(!model)return;if(!available.some(m=>m.id===modelId))modelId=model.id;if(model.ratios.length&&!model.ratios.includes(aspectRatio))aspectRatio=model.ratios[0];if(model.resolutions.length&&!model.resolutions.includes(resolution))resolution=model.resolutions[0];if(model.durations.length&&!model.durations.includes(duration))duration=model.durations[0];});
 onMount(()=>{editablePrompt=prompt;refresh();const timer=setInterval(poll,2400);return()=>clearInterval(timer);});
 async function refresh(){try{session=await apiRequest('/session');wallet=await apiRequest('/wallet');jobs=(await apiRequest('/jobs')).jobs;loaded=true;}catch(e){error=e.message;}}
 async function poll(){if(busy||!loaded)return;let changed=false;for(const job of jobs.filter(j=>['queued','processing'].includes(j.state))){try{const data=await apiRequest('/jobs/'+job.id);jobs=jobs.map(j=>j.id===job.id?data.job:j);if(['completed','failed','canceled'].includes(data.job.state)){changed=true;if(data.job.state==='completed')notify(data.job.mode==='mock'?'Mock workflow completed. Demo output is ready.':'Generation completed. Result is ready.');}}catch(e){error=e.message;}}if(changed){wallet=await apiRequest('/wallet');await onassetschange();}}
 async function generate(){if(busy)return;busy=true;error='';try{
  if(!intent)intent=crypto.randomUUID();
  let source=assets.find(a=>a.id===(sourceAssetId||scene?.approvedImageId)),sourceId=source?.id;
  const refs=assets.filter(a=>(scene?.referenceBindings?.[a.type+':'+a.ownerId]?a.id===scene.referenceBindings[a.type+':'+a.ownerId]:a.approved)&&((a.type==='character'&&scene?.characterIds?.includes(a.ownerId))||(a.type==='location'&&[scene?.locationId,...(scene?.additionalLocationIds||[])].includes(a.ownerId))));
  const refIds=[];for(const ref of refs){refIds.push(await syncLocalAsset(ref,storyId));if(scene)scene.referenceBindings={...scene.referenceBindings,[ref.type+':'+ref.ownerId]:ref.id};}
  if(kind==='image-to-video'){if(!source)throw Error('Choose an approved or uploaded image from this scene.');sourceId=await syncLocalAsset(source,storyId);}
  const request={storyId,sceneId:scene?.id||null,kind,entityId,modelId:model.id,title:title||scene?.title||kind,prompt:editablePrompt,sceneDescription:scene?.text||'',characterIds:scene?.characterIds||[],locationIds:[scene?.locationId,...(scene?.additionalLocationIds||[])].filter(Boolean),referenceIds:refIds,sourceAssetId:sourceId||null,settings:{aspectRatio,resolution,duration}};
  const data=await apiRequest('/jobs',{method:'POST',headers:{'Idempotency-Key':intent},body:JSON.stringify(request)});jobs=[data.job,...jobs.filter(j=>j.id!==data.job.id)];intent=null;wallet=await apiRequest('/wallet');
 }catch(e){error=e.message;if(e.status&&e.status<500)intent=null;}finally{busy=false;}}
 async function cancel(job){try{await apiRequest('/jobs/'+job.id+'/cancel',{method:'POST',body:'{}'});await refresh();}catch(e){error=e.message;}}
 async function recover(job,reconcile=false){try{await apiRequest('/jobs/'+job.id+(reconcile?'/reconcile':''),reconcile?{method:'POST',body:'{}'}:{});await refresh();await onassetschange();}catch(e){error=e.message;}}
 async function uploadVideo(e){const file=e.currentTarget.files?.[0];if(!file||!scene)return;busy=true;error='';try{if(file.size>20*1024*1024)throw Error('Choose a video smaller than 20 MB.');await apiRequest('/assets',{method:'POST',headers:{'Content-Type':file.type,'X-Quill-Asset':encodeURIComponent(JSON.stringify({type:'video',ownerId:scene.id,storyId,source:'Uploaded video'}))},body:file});await onassetschange();notify('Video uploaded. Choose it as this scene’s approved video.');}catch(err){error=err.message;}finally{busy=false;e.target.value='';}}
 function approve(job){if(!scene||!job.assetId)return;const a=assets.find(a=>a.id===job.assetId);if(a?.type==='scene'){scene.approvedImageId=job.assetId;notify('Demo image approved for this scene only');}else if(a?.type==='video'){scene.approvedVideoId=job.assetId;notify('Motion demo linked to this scene');}}
</script>
<section class="generation-studio" aria-label="AI Generation Studio">
 <div class="generation-title"><div><span class="eyebrow">HIGGSFIELD READY</span><h3>AI Generation Studio</h3></div><span class="generation-mode">{session?.mode||'Connecting'} mode</span></div>
 <div class="generation-warning"><ShieldCheck size={17}/><span><strong>Higgsfield API Not Connected</strong><small>Demo workflows only. No paid API requests. Credits and subscriptions are previews.</small></span></div>
 <div class="generation-settings"><label>Generation type<input readonly value={kind.replaceAll('-',' ')}/></label><label>Model<select bind:value={modelId}>{#each available as m}<option value={m.id}>{m.name} · Preview only</option>{/each}</select></label>{#if model?.ratios.length}<label>Aspect ratio<select bind:value={aspectRatio}>{#each model.ratios as r}<option>{r}</option>{/each}</select></label>{/if}{#if model?.resolutions.length}<label>Resolution<select bind:value={resolution}>{#each model.resolutions as r}<option>{r}</option>{/each}</select></label>{/if}{#if model?.durations.length}<label>Duration<select bind:value={duration}>{#each model.durations as d}<option value={d}>{d} seconds</option>{/each}</select></label>{/if}</div>
 {#if model?.source}<p class="generation-source">Documented schema, account access unverified. <a href={model.source} target="_blank" rel="noreferrer">Official model specification ↗</a></p>{:else}<p class="generation-source">Reference-aware scene capability is a preview. A live model schema must be verified before activation.</p>{/if}
 {#if kind==='image-to-video'}<label class="director-field">Exact starting image<select bind:value={sourceAssetId}><option value="">Use this scene’s approved image</option>{#each assets.filter(a=>a.type==='scene'&&a.storyId===storyId&&a.ownerId===scene?.id) as a}<option value={a.id}>{a.mock?'Demo':'Image'} {a.id.slice(0,12)}</option>{/each}</select></label>{#if assets.find(a=>a.id===(sourceAssetId||scene?.approvedImageId))}<img class="generation-first-frame" src={assets.find(a=>a.id===(sourceAssetId||scene?.approvedImageId)).url} alt="Exact selected starting frame"/>{/if}{/if}
 <label class="director-field">Review the generation prompt<textarea class="generation-prompt" bind:value={editablePrompt}></textarea></label><div class="prompt-actions"><button class="text-button" onclick={()=>{editablePrompt=prompt;intent=null;}}>Use current Scene Director prompt <RefreshCw size={13}/></button></div>
 <div class="generation-credit-row"><span><strong>{estimate}</strong> preview credits estimated <small>{wallet?.available??'…'} available · no monetary value</small></span><button class="button primary" disabled={busy||!model||!editablePrompt.trim()||session?.mode==='disabled'||(wallet?.available||0)<estimate} onclick={generate}><Sparkles size={15}/>{busy?'Submitting…':session?.mode==='live'?'Generate':'Run mock generation'}</button></div>
 {#if error}<p class="director-error" role="alert">{error}</p>{/if}
 {#if scene}<div class="uploaded-videos"><label class="button secondary upload-control"><Film size={14}/> Upload scene video<input type="file" accept="video/mp4,video/webm" disabled={busy} onchange={uploadVideo}/></label>{#each assets.filter(a=>a.type==='video'&&a.ownerId===scene.id&&a.storyId===storyId&&a.mime?.startsWith('video/')) as video}<article><video controls src={video.url} playsinline><track kind="captions"/></video><button class="button secondary" onclick={()=>{scene.approvedVideoId=video.id;notify('Uploaded video approved for this scene');}}>{scene.approvedVideoId===video.id?'Approved scene video':'Use this video'}</button></article>{/each}</div>{/if}
 <div class="generation-history"><h4>Generation history <span>{sceneJobs.length}</span></h4>{#if !sceneJobs.length}<p>No generations yet. Review your settings, then explicitly start a mock job.</p>{/if}{#each sceneJobs as job}{@const output=assets.find(a=>a.id===job.assetId)}<article><div class="job-heading"><strong>{job.kind.replaceAll('-',' ')}</strong><span class={`job-state ${job.state}`}>{job.state}</span></div><small>{new Date(job.createdAt).toLocaleString()} · {job.mode.toUpperCase()} · {job.id.slice(0,8)}</small>{#if ['queued','processing'].includes(job.state)}<progress max="100" value={job.progress} aria-label="Mock workflow progress"></progress><p>{job.mode==='mock'?'Simulated progress. No external generation is running.':'Provider is processing; progress percentage is an estimate.'}</p>{/if}{#if output}<div class="mock-result-label">DEMO OUTPUT · NOT AI GENERATED</div>{#if output.mime?.startsWith('video/')}<video controls src={output.url} playsinline><track kind="captions"/></video>{:else}<img class="generation-result" src={output.url} alt={`${job.mode} ${job.kind} workflow demonstration`}/>{/if}{#if output.motionPreview}<p>Animated placeholder for the video workflow. It is not a rendered video and does not animate your selected source image.</p>{/if}<div class="prompt-actions"><a class="button secondary" href={output.url} download={`quill-${job.id}-${output.mime?.startsWith('video/')?'video':'demo'}.${output.mime?.startsWith('video/')?'mp4':'svg'}`}><Download size={13}/> Download demo</a>{#if scene}<button class="button secondary" onclick={()=>approve(job)}>Use in this scene <ArrowRight size={13}/></button>{/if}</div>{/if}{#if job.state==='queued'}<button class="text-button" onclick={()=>cancel(job)}>Cancel queued job <X size={12}/></button>{/if}{#if job.state==='submission_uncertain'}<button class="button secondary" onclick={()=>recover(job,true)}>Reconcile original submission</button>{/if}{#if job.state==='completed'&&!job.assetId}<button class="button secondary" onclick={()=>recover(job)}>Retry saving result</button>{/if}{#if job.state==='failed'}<p>{job.error}</p><button class="text-button" onclick={()=>{editablePrompt=job.prompt;modelId=available.find(m=>m.capabilities.includes(kind))?.id;intent=null;}}>Prepare a new retry <RefreshCw size={12}/></button>{/if}{#if job.error}<p class="director-error">{job.error}</p>{/if}</article>{/each}</div>
</section>
